# Snippet 3: Run Motter-Lai cascade for each of the top-5 busiest buses and record largest component size
top5_candidates = [68, 76, 64, 79, 37]

# Use initial loads from betweenness (bet) as "LOAD" and compute capacities once
initial_loads = bet  # from previous snippet
capacities = {n: 1.2 * initial_loads[n] for n in G.nodes()}

cascade_results = {}

for trigger in top5_candidates:
    curG = G.copy()
    if curG.has_node(trigger):
        curG.remove_node(trigger)
    else:
        cascade_results[trigger] = 0
        continue

    # If nothing left, largest component size is 0
    if curG.number_of_nodes() == 0:
        cascade_results[trigger] = 0
        continue

    while True:
        bet_cur = nx.betweenness_centrality(curG, normalized=False)
        overloaded = [n for n in curG.nodes() if bet_cur.get(n, 0) > capacities[n]]
        if not overloaded:
            break
        curG.remove_nodes_from(overloaded)
        if curG.number_of_nodes() == 0:
            break

    if curG.number_of_nodes() == 0:
        size = 0
    else:
        largest = max(nx.connected_components(curG), key=len)
        size = len(largest)

    cascade_results[trigger] = size

print("CASCADE_RESULT_SIZES:", cascade_results)

# Determine the bus whose triggering yields the largest remaining network
best_trigger = max(cascade_results.items(), key=lambda kv: kv[1])[0]
best_size = cascade_results[best_trigger]
print("BEST_TRIGGER:", best_trigger, "SIZE:", best_size)

